#include "../RahiTuber/CameraFrame.h"
#include <iostream>
#include <stdexcept>
#include <cstring>
int main(){using namespace MaxCameraFrame;Header h;unsigned char bytes[64];std::memcpy(bytes,&h,64);std::uint32_t magic;std::memcpy(&magic,bytes,4);if(magic!=Magic||h.width!=640||h.height!=480||h.active!=0)throw std::runtime_error("Incorrect camera header");const unsigned char rgba[]={255,0,0,30,0,255,0,80,0,0,255,200,10,20,30,255};unsigned char bgra[16]={};RgbaToBgra(rgba,bgra,4);if(bgra[0]!=0||bgra[2]!=255||bgra[5]!=255||bgra[8]!=255||bgra[12]!=30||bgra[14]!=10)throw std::runtime_error("Wrong camera color order");for(int i=3;i<16;i+=4)if(bgra[i]!=255)throw std::runtime_error("Camera output must be opaque");Cadence cadence;int sent=0;for(std::int64_t t=0;t<1000000;t+=16667)if(cadence.Due(t))sent++;if(sent<29||sent>31)throw std::runtime_error("Camera drops to 20 FPS at a 60 FPS render rate");if(!cadence.Due(5000000)||cadence.Due(5000001))throw std::runtime_error("Camera bursts after a pause");std::cout<<"PASS: camera header, color order, opacity and 30 FPS cadence\n";}
